<?php
/* CCS v110: CLI-only, explicit .store/.lk targets, preflight, backups and additive catalogue import. */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('CLI only'); }
error_reporting(E_ALL);
ini_set('display_errors','1');
const CCS_PAYLOAD_V110 = '';
const CCS_MANIFEST_V110 = '';
function blob110(string $data): string {return sha1('blob '.strlen($data)."\0".$data);}
function normalized110(string $data): string {return str_replace('ccssolutions.store','ccssolutions.lk',$data);}
function checkedWrite110(string $path,string $bytes): void {
    if (is_link($path)) throw new RuntimeException('Refusing symlink: '.$path);
    if (!is_dir(dirname($path)) && !mkdir(dirname($path),0755,true)) throw new RuntimeException('Cannot create directory');
    $tmp=tempnam(dirname($path),'.v110-');
    if ($tmp===false) throw new RuntimeException('Cannot create temporary file');
    try {
        if (file_put_contents($tmp,$bytes)!==strlen($bytes)) throw new RuntimeException('Short write: '.$path);
        chmod($tmp,0644);
        if (!rename($tmp,$path)) throw new RuntimeException('Cannot replace: '.$path);
    } finally {if (is_file($tmp)) unlink($tmp);}
}
try {
    $files=json_decode(gzdecode(base64_decode(CCS_PAYLOAD_V110,true)),true,512,JSON_THROW_ON_ERROR);
    $manifest=json_decode(base64_decode(CCS_MANIFEST_V110,true),true,512,JSON_THROW_ON_ERROR);
    foreach($files as $name=>$encoded){
        $bytes=base64_decode($encoded,true);
        if ($bytes===false || hash('sha256',$bytes)!==$manifest[$name]['sha256']) throw new RuntimeException('Damaged payload: '.$name);
    }
    $dry=in_array('--check',$argv,true);
    $both=in_array('--both',$argv,true);
    $domains=dirname(dirname(__DIR__));
    $targets=$both?[$domains.'/ccssolutions.store',$domains.'/ccssolutions.lk']:[dirname(__DIR__)];
    $targets=array_map(fn($d)=>realpath($d)?:throw new RuntimeException('Missing domain directory: '.$d),$targets);
    foreach($targets as $domain){
        if (!in_array(basename($domain),['ccssolutions.store','ccssolutions.lk'],true)) throw new RuntimeException('Run the installer from the private ccs-admin-app folder.');
        foreach(['ccs-admin-app/.env','ccs-admin-app/vendor/autoload.php','ccs-admin-app/bootstrap/app.php','public_html/admin/index.php'] as $required) if(!is_file($domain.'/'.$required)) throw new RuntimeException('Missing required file: '.$required);
        foreach($files as $name=>$encoded){
            $path=$domain.'/'.$name;
            if(is_link($path))throw new RuntimeException('Refusing symlink: '.$name);
            $parent=dirname($path);
            while(!file_exists($parent))$parent=dirname($parent);
            $real=realpath($parent);
            if(!$real||!str_starts_with($real.'/',$domain.'/')||!is_writable($real))throw new RuntimeException('Unsafe/unwritable destination: '.$name);
            if(is_file($path)){
                $current=file_get_contents($path);
                if(hash('sha256',$current)===$manifest[$name]['sha256'])continue;
                $expected=$manifest[$name]['baseline']??null;
                if(!$expected||blob110(normalized110($current))!==$expected)throw new RuntimeException('File changed since the inspected GitHub backup: '.basename($domain).'/'.$name.'. Nothing overwritten. Send this message for a merge.');
            } elseif(!empty($manifest[$name]['baseline']))throw new RuntimeException('Expected original file is missing: '.$name);
        }
    }
    // Boot each site in its own PHP process: never reuse a Laravel container across domains.
    if($both){
        foreach($targets as $domain){
            if(realpath($domain.'/ccs-admin-app')!==realpath(__DIR__)){
                $copy=$domain.'/ccs-admin-app/install-catalogue-v110.php';
                if(is_file($copy)&&hash_file('sha256',$copy)!==hash_file('sha256',__FILE__))throw new RuntimeException('Different installer already exists in LK app.');
            }
        }
        echo "File preflight passed for both domains.\n";
        echo "Run this installer separately in each domain so each site boots its own Laravel configuration.\n";
        echo "Use --check and then install without --both in .store, followed by .lk.\n";
        exit(0);
    }
    $domain=$targets[0];$appRoot=$domain.'/ccs-admin-app';
    require $appRoot.'/vendor/autoload.php';
    $app=require $appRoot.'/bootstrap/app.php';
    $kernel=$app->make(Illuminate\Contracts\Console\Kernel::class);
    $kernel->bootstrap();
    $connection=Illuminate\Support\Facades\DB::connection();
    if($connection->getDriverName()!=='sqlite')throw new RuntimeException('This installer requires the inspected SQLite deployment.');
    $database=realpath($connection->getDatabaseName());
    if(!$database||!str_starts_with($database,$appRoot.'/database/'))throw new RuntimeException('Database is outside this domain. Fix the domain DB_DATABASE before installing.');
    $pdo=$connection->getPdo();$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec('PRAGMA busy_timeout=15000');
    $columns=$pdo->query('PRAGMA table_info(ccs_website_content)')->fetchAll(PDO::FETCH_COLUMN,1);
    foreach(['id','kind','slug','title','active','sort_order','data','revision','updated_by','created_at','updated_at'] as $column)if(!in_array($column,$columns,true))throw new RuntimeException('Catalogue table/schema missing: '.$column.'. No migration run.');
    $importer=base64_decode($files['ccs-admin-app/app/Support/CcsCatalogueImportV110.php'],true);
    eval(substr($importer,5));
    $vehicles=json_decode(base64_decode($files['ccs-admin-app/database/data/ccs-catalogue-v110.json'],true),true,512,JSON_THROW_ON_ERROR);
    $stats=CcsCatalogueImportV110::apply($pdo,$vehicles,true);
    foreach(['customer.login','customer.login.submit','customer.email.request','customer.email.verify','ccs.website.content.public'] as $route){if(!Illuminate\Support\Facades\Route::has($route))throw new RuntimeException('Required existing route missing: '.$route);}
    echo basename($domain).': catalogue plan '.json_encode($stats)."\n";
    if($dry){echo "v110 checks passed. No files or catalogue rows changed.\n";exit(0);}
    $backup=$appRoot.'/storage/app/ccs-code-backups/v110-'.date('Ymd-His').'-'.bin2hex(random_bytes(3));
    if(!mkdir($backup,0700,true))throw new RuntimeException('Cannot create backup');
    $pdo->exec('VACUUM INTO '.$pdo->quote($backup.'/database.sqlite'));
    $existed=[];
    foreach($files as $name=>$encoded){
        $path=$domain.'/'.$name;$existed[$name]=is_file($path);
        if($existed[$name]){
            $dest=$backup.'/files/'.$name;
            if(!is_dir(dirname($dest))&&!mkdir(dirname($dest),0700,true))throw new RuntimeException('Backup directory failed');
            if(!copy($path,$dest))throw new RuntimeException('Backup failed: '.$name);
        }
    }
    file_put_contents($backup.'/manifest.json',json_encode($existed,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
    $written=[];
    try{
        $pdo->beginTransaction();
        $stats=CcsCatalogueImportV110::apply($pdo,$vehicles,false);
        foreach($files as $name=>$encoded){checkedWrite110($domain.'/'.$name,base64_decode($encoded,true));$written[]=$name;}
        // Compile Blade before committing so syntax failures restore both files and catalogue changes.
        if($kernel->call('view:cache')!==0)throw new RuntimeException('View compilation failed: '.$kernel->output());
        if($kernel->call('view:clear')!==0)throw new RuntimeException('View cache clear failed');
        $pdo->commit();
    }catch(Throwable $e){
        if($pdo->inTransaction())$pdo->rollBack();
        foreach(array_reverse($written) as $name){if($existed[$name])checkedWrite110($domain.'/'.$name,file_get_contents($backup.'/files/'.$name));else @unlink($domain.'/'.$name);}
        $kernel->call('view:clear');
        throw $e;
    }
    foreach($manifest as $name=>$entry)if(hash_file('sha256',$domain.'/'.$name)!==$entry['sha256'])throw new RuntimeException('Post-install checksum mismatch: '.$name);
    echo "v110 installed on ".basename($domain).". Catalogue: ".json_encode($stats)."\n";
    echo "Backup: $backup\nAll update file checksums match. No customer/stock/invoice tables changed.\n";
}catch(Throwable $e){fwrite(STDERR,"STOP: ".$e->getMessage()."\n");exit(1);}
